        function t(key) { return translations[currentLanguage]?.[key] || translations['en'][key] || key; }
        function setLanguage(lang) { currentLanguage = lang; document.documentElement.lang = lang; /* 佈局統一 LTR：不切換 dir=rtl，避免 nav/區塊鏡像與位置漂移；阿文文字方向由 CSS 處理 */ const langSel = document.getElementById('langSelect'); if (langSel) langSel.value = lang; try { localStorage.setItem('gp-lang', lang); } catch (e) {} applyAllTranslations(); renderProducts(); renderCaseFilters(); renderCases(); renderClients(); renderScope(); renderScopeModes(); const cw = document.getElementById('chatWindow'); if (cw && cw.classList.contains('open')) { refreshChatI18n(); renderQuickReplies(); } }
        // ===== 語言自動偵測：① 瀏覽器語言 + ② 時區推測（手動選擇優先記憶） =====
        const SITE_LANGS = ['en','zh-Hant','zh-CN','ko','ja','th','fr','ar'];
        function getSavedLang() { try { const s = localStorage.getItem('gp-lang'); return SITE_LANGS.includes(s) ? s : null; } catch (e) { return null; } }
        function normalizeBrowserLang(raw) {
            if (!raw) return null;
            const l = String(raw).toLowerCase().replace(/_/g, '-');
            if (l.indexOf('zh') === 0) {
                if (l.indexOf('hant') > -1 || l.indexOf('tw') > -1 || l.indexOf('hk') > -1 || l.indexOf('mo') > -1) return 'zh-Hant';
                if (l.indexOf('hans') > -1 || l.indexOf('cn') > -1 || l.indexOf('sg') > -1 || l.indexOf('my') > -1) return 'zh-CN';
                return null; // 泛 zh → 交給時區判斷繁簡
            }
            if (l.indexOf('ko') === 0) return 'ko';
            if (l.indexOf('ja') === 0) return 'ja';
            if (l.indexOf('th') === 0) return 'th';
            if (l.indexOf('fr') === 0) return 'fr';
            if (l.indexOf('ar') === 0) return 'ar';
            if (l.indexOf('en') === 0) return 'en';
            return null;
        }
        function timezoneToLang() {
            try {
                const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
                if (!tz) return null;
                const T = tz.toUpperCase();
                if (T.indexOf('TOKYO') > -1) return 'ja';
                if (T.indexOf('SEOUL') > -1) return 'ko';
                if (T.indexOf('BANGKOK') > -1) return 'th';
                if (T.indexOf('PARIS') > -1) return 'fr';
                if (T.indexOf('TAIPEI') > -1 || T.indexOf('HONG_KONG') > -1 || T.indexOf('MACAU') > -1) return 'zh-Hant';
                if (T.indexOf('SHANGHAI') > -1 || T.indexOf('CHONGQING') > -1 || T.indexOf('HARBIN') > -1 || T.indexOf('URUMQI') > -1 || T.indexOf('UYANGA') > -1) return 'zh-CN';
                if (T.indexOf('DUBAI') > -1 || T.indexOf('RIYADH') > -1 || T.indexOf('QATAR') > -1 || T.indexOf('CAIRO') > -1 || T.indexOf('KUWAIT') > -1 || T.indexOf('BAHRAIN') > -1 || T.indexOf('MUSCAT') > -1 || T.indexOf('AMMAN') > -1 || T.indexOf('BEIRUT') > -1 || T.indexOf('CASABLANCA') > -1) return 'ar';
                return null;
            } catch (e) { return null; }
        }
        function detectPreferredLang() {
            const saved = getSavedLang();
            if (saved) return saved; // 手動選擇過 → 以手動為準
            let firstSignal = null; // 'match'（明確匹配）或 'zh'（泛 zh）
            let firstMatch = null;
            try {
                const navLangs = (navigator.languages && navigator.languages.length) ? navigator.languages : [navigator.language || ''];
                for (let i = 0; i < navLangs.length; i++) {
                    const m = normalizeBrowserLang(navLangs[i]);
                    if (m) { if (firstSignal === null) firstSignal = 'match'; if (!firstMatch) firstMatch = m; break; }
                    const l = String(navLangs[i] || '').toLowerCase().replace(/_/g, '-');
                    if (l.indexOf('zh') === 0 && firstSignal === null) firstSignal = 'zh'; // 泛 zh 優先於後續語言，交給時區裁決繁簡
                }
            } catch (e) {}
            if (firstSignal === 'match') return firstMatch; // ① 瀏覽器語言命中
            const tzLang = timezoneToLang(); // ② 時區推測
            if (firstSignal === 'zh') { if (tzLang === 'zh-Hant' || tzLang === 'zh-CN') return tzLang; return 'en'; }
            return tzLang || 'en';
        }
        function applyAllTranslations() { document.querySelectorAll('[data-i18n]').forEach(el => { const key = el.getAttribute('data-i18n'); if (translations[currentLanguage]?.[key]) { const val = translations[currentLanguage][key]; if (val.includes('<br>')) el.innerHTML = val; else el.textContent = val; } }); document.querySelectorAll('[data-i18n-nav]').forEach(link => { link.textContent = t('nav_' + link.getAttribute('data-i18n-nav')); }); document.querySelectorAll('[data-i18n-mobile]').forEach(link => { link.textContent = t('nav_' + link.getAttribute('data-i18n-mobile')); }); document.querySelectorAll('[data-i18n-placeholder]').forEach(el => { el.placeholder = t(el.getAttribute('data-i18n-placeholder')); }); }
        function getInitialTheme() { try { const saved = localStorage.getItem('gp-theme'); if (saved === 'light' || saved === 'dark') return saved; } catch (e) {} return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'; }
        function applyTheme(theme) { currentTheme = theme; document.documentElement.setAttribute('data-theme', theme); document.getElementById('themeToggle').textContent = theme === 'light' ? '🌙' : '☀️'; }
        function toggleTheme() { applyTheme(currentTheme === 'light' ? 'dark' : 'light'); try { localStorage.setItem('gp-theme', currentTheme); } catch (e) {} }
        function toggleFaq(btn) { const item = btn.parentElement; const wasOpen = item.classList.contains('open'); document.querySelectorAll('.faq-item.open').forEach(function(i) { i.classList.remove('open'); const b = i.querySelector('.faq-q'); if (b) b.setAttribute('aria-expanded', 'false'); }); if (!wasOpen) { item.classList.add('open'); btn.setAttribute('aria-expanded', 'true'); } }
        /* 聊天機器人 */
        function isBusinessHoursHKT() { try { const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Hong_Kong' })); const day = now.getDay(), hour = now.getHours(); if (day === 0) return false; if (day === 6) return hour >= 10 && hour < 14; return hour >= 9 && hour < 18; } catch (e) { return true; } }
        function toggleChat() { const w = document.getElementById('chatWindow'); if (!w) return; const open = w.classList.contains('open'); if (open) { w.classList.remove('open'); w.setAttribute('aria-hidden', 'true'); return; } w.classList.add('open'); w.setAttribute('aria-hidden', 'false'); refreshChatI18n(); renderQuickReplies(); const body = document.getElementById('chatBody'); if (body && !body.dataset.ready) { body.dataset.ready = '1'; const online = isBusinessHoursHKT(); updateChatStatus(online); addChatMsg(online ? t('chatGreeting') : t('chatOfflineMsg'), 'bot'); } }
        function updateChatStatus(online) { const dot = document.getElementById('chatStatusDot'); const tx = document.getElementById('chatStatusText'); if (!dot || !tx) return; dot.className = online ? 'on' : 'off'; const v = online ? t('chatOnline') : t('chatOffline'); if (v && v !== 'chatOnline' && v !== 'chatOffline') tx.textContent = v; }
        function refreshChatI18n() { document.querySelectorAll('#chatWindow [data-i18n]').forEach(function(el) { const k = el.getAttribute('data-i18n'); const v = t(k); if (v && v !== k) el.textContent = v; }); const ip = document.getElementById('chatInput'); if (ip) { const v = t('chatPlaceholder'); if (v) ip.placeholder = v; } updateChatStatus(isBusinessHoursHKT()); }
        function addChatMsg(text, who) { const body = document.getElementById('chatBody'); if (!body) return null; const d = document.createElement('div'); d.className = 'chat-msg ' + who; d.textContent = text; body.appendChild(d); body.scrollTop = body.scrollHeight; return d; }
        function renderQuickReplies() { const c = document.getElementById('chatQuick'); if (!c) return; c.innerHTML = ''; const keys = ['chatQuick1', 'chatQuick2', 'chatQuick3', 'chatQuick4', 'chatQuick5', 'chatQuick8']; keys.forEach(function(k) { const b = document.createElement('button'); b.type = 'button'; b.textContent = t(k) || k; b.onclick = function() { quickReply(k); }; c.appendChild(b); }); const cb = document.createElement('button'); cb.type = 'button'; cb.className = 'chat-callback-btn'; cb.textContent = t('chatCallback'); cb.onclick = showCallbackForm; c.appendChild(cb); }
        function showTyping() { const body = document.getElementById('chatBody'); if (!body || document.getElementById('chatTyping')) return; const d = document.createElement('div'); d.className = 'chat-typing'; d.id = 'chatTyping'; d.innerHTML = '<span></span><span></span><span></span>'; body.appendChild(d); body.scrollTop = body.scrollHeight; }
        function hideTyping() { const el = document.getElementById('chatTyping'); if (el) el.remove(); }
        function quickReply(key) { const map = { chatQuick1: 1, chatQuick2: 2, chatQuick3: 3, chatQuick4: 4, chatQuick5: 5, chatQuick8: 8 }; addChatMsg(t(key) || key, 'user'); botReply(map[key] || 1); }
        function sendChat() { const input = document.getElementById('chatInput'); if (!input) return; const text = input.value.trim(); if (!text) return; addChatMsg(text, 'user'); input.value = ''; botReply(0, text); }
        function botReply(faqIdx, raw) { showTyping(); setTimeout(function() { hideTyping(); const reply = faqIdx ? t('faqA' + faqIdx) : getAutoReply(raw || ''); addChatMsg(reply, 'bot'); }, 900); }
        function getAutoReply(text) { const l = text.toLowerCase(); if (/(moq|minimum|quantity|min\.?\s?order|数量|數量|最低|起订|起訂|수량|최소|最小|จำนวน|quantité|كمية|الحد)/.test(l)) return t('faqA1'); if (/(sample|prototype|打样|打樣|样品|樣品|샘플|サンプル|ตัวอย่าง|échantillon|عينة)/.test(l)) return t('faqA2'); if (/(lead\s?time|deliver|交期|货期|交貨|出貨|出货|납기|リードタイム|ระยะเวลา|délai|تسليم)/.test(l)) return t('faqA3'); if (/(payment|pay|付款|支付|결제|支払い|การชำระ|paiement|دفع)/.test(l)) return t('faqA4'); if (/(ship|logistic|delivery|物流|運輸|运输|配送|배송|配送|จัดส่ง|expédition|livraison|شحن)/.test(l)) return t('faqA5'); if (/(eco|recycl|環保|环保|친환경|環境|écolog|صديقة للبيئة|รักษ์โลก)/.test(l)) return t('faqA6'); if (/(custom|客制|客製|定制|定製|커스텀|カスタム|personnalis|تخصيص)/.test(l)) return t('faqA7'); if (/(quality|品质|品質|품질|品質|คุณภาพ|qualité|جودة)/.test(l)) return t('faqA8'); if (/(logo|print|印刷|打印|印製|로고|ロゴ|โลโก้|impression|شعار)/.test(l)) return t('faqA9'); if (/(foil|stamp|uv|emboss|finish|工艺|工藝|后加工|後加工|烫金|燙金|가공|후가공|仕上げ|finition|تشطيب)/.test(l)) return t('faqA10'); if (/(overseas|寄样|寄樣|해외|海外|étranger|خارج)/.test(l)) return t('faqA11'); return t('chatDefault'); }
        function showCallbackForm() { const online = isBusinessHoursHKT(); addChatMsg(t('chatCallback'), 'user'); setTimeout(function() { addChatMsg(online ? t('cbPromptOnline') : t('cbPromptOffline'), 'bot'); const body = document.getElementById('chatBody'); if (!body || document.getElementById('callbackForm')) return; const form = document.createElement('div'); form.className = 'chat-callback-form'; form.id = 'callbackForm'; form.innerHTML = '<div class="cf-field"><label>' + t('cbName') + '</label><input type="text" id="cbName" aria-label="' + t('cbName') + '"></div><div class="cf-field"><label>' + t('cbPhone') + '</label><input type="tel" id="cbPhone" aria-label="' + t('cbPhone') + '"></div><div class="cf-field"><label>' + t('cbQuestion') + '</label><textarea id="cbQuestion" rows="2" aria-label="' + t('cbQuestion') + '"></textarea></div><button class="cf-submit" onclick="submitCallback()">' + t('cbSubmit') + '</button><div class="cf-note">' + t('cbNote') + '</div>'; body.appendChild(form); body.scrollTop = body.scrollHeight; }, 600); }
        function submitCallback() { const name = (document.getElementById('cbName') || {}).value ? document.getElementById('cbName').value.trim() : ''; const phone = (document.getElementById('cbPhone') || {}).value ? document.getElementById('cbPhone').value.trim() : ''; if (!name || !phone) { alert(t('cbRequired')); return; } const question = (document.getElementById('cbQuestion') || {}).value ? document.getElementById('cbQuestion').value.trim() : ''; const online = isBusinessHoursHKT(); const subject = encodeURIComponent('[Callback Request] ' + name + ' - ' + phone); const bodyText = encodeURIComponent('Name: ' + name + '\nPhone/Email: ' + phone + '\nQuestion: ' + (question || '-') + '\nSubmitted: ' + new Date().toLocaleString('en-US', { timeZone: 'Asia/Hong_Kong' }) + ' HKT'); window.location.href = 'mailto:sales@genesisplus.net?subject=' + subject + '&body=' + bodyText; const f = document.getElementById('callbackForm'); if (f) f.remove(); addChatMsg(online ? t('cbConfirmOnline') : t('cbConfirmOffline'), 'bot'); try { const records = JSON.parse(localStorage.getItem('gp_callbacks') || '[]'); records.push({ name: name, phone: phone, question: question, time: new Date().toISOString(), online: online }); localStorage.setItem('gp_callbacks', JSON.stringify(records)); } catch (e) {} }
        function closeMobileMenu() { const menu = document.getElementById('mobileMenu'); const btn = document.getElementById('mobileMenuBtn'); if (menu) menu.classList.remove('open'); if (btn) btn.classList.remove('active'); }
        function toggleMobileMenu() { const menu = document.getElementById('mobileMenu'); const btn = document.getElementById('mobileMenuBtn'); menu.classList.toggle('open'); btn.classList.toggle('active'); btn.setAttribute('aria-expanded', menu.classList.contains('open') ? 'true' : 'false'); }
        function makeCardAccessible(el, label, handler) { el.tabIndex = 0; el.setAttribute('role', 'button'); el.setAttribute('aria-label', label || ''); el.addEventListener('keydown', function(e) { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); handler(); } }); }

        function renderProducts() { if (!productsGrid) return; const gpItems = (document.body.getAttribute('data-page') === 'home') ? productsData.slice(0, 6) : productsData; productsGrid.innerHTML = ''; gpItems.forEach(product => { const card = document.createElement('div'); card.className = 'product-card'; const src400 = product.img.replace(/\.jpg$/, '-400.jpg'); card.innerHTML = `<div class="product-image"><img src="${product.img}" srcset="${src400} 400w, ${product.img} 800w" sizes="(max-width:768px) 45vw, 280px" alt="${t(product.nameKey)}" loading="lazy" onerror="this.style.display='none'"></div><div class="product-body"><div class="product-name">${product.icon} ${t(product.nameKey)}</div><div class="product-desc">${product.desc[currentLanguage] || product.desc['en']}</div></div>`; card.onclick = () => openProductModal(product.id); makeCardAccessible(card, t(product.nameKey), function() { openProductModal(product.id); }); productsGrid.appendChild(card); }); }
        function renderCaseFilters() { if (!caseFilters) return; const cats = ['all','food','electronics','cosmetics','retail','sustainable','perfume']; caseFilters.innerHTML = ''; cats.forEach(cat => { const btn = document.createElement('button'); btn.className = `filter-btn ${cat === activeCaseFilter ? 'active' : ''}`; btn.textContent = t('filter' + (cat === 'all' ? 'All' : cat.charAt(0).toUpperCase() + cat.slice(1))); btn.onclick = () => { activeCaseFilter = cat; renderCaseFilters(); renderCases(); }; caseFilters.appendChild(btn); }); }
        function renderCases() { if (!casesGrid) return; const gpPool = (document.body.getAttribute('data-page') === 'home') ? casesData.slice(0, 4) : casesData; casesGrid.innerHTML = ''; const filtered = activeCaseFilter === 'all' ? gpPool : gpPool.filter(c => c.category === activeCaseFilter); filtered.forEach(caseItem => { const title = caseTitlesData[caseItem.id]?.[currentLanguage] || ''; const desc = caseDescMap[caseItem.descKey]?.[currentLanguage] || ''; const tag = t(caseItem.tagKey); const card = document.createElement('div'); card.className = 'case-card'; card.innerHTML = `<div class="case-visual"><div class="case-visual-bg" style="background-image:url('${caseItem.bg}')"></div></div><div class="case-info"><span class="case-tag">${tag}</span><h3>${title}</h3><p>${desc}</p></div>`; card.onclick = () => openCaseModal(caseItem.id); makeCardAccessible(card, title, function() { openCaseModal(caseItem.id); }); casesGrid.appendChild(card); }); }

        // ===== 渲染 clients（固定宽度 + 调大文字） =====
        function renderClients() { 
            if (!clientsGrid) return; 
            clientsGrid.innerHTML = ''; 
            clientLogos.forEach(logo => { 
                const wrapper = document.createElement('div'); 
                wrapper.className = 'client-item'; 
                
                const gridDiv = document.createElement('div'); 
                gridDiv.className = 'client-logo'; 
                const img = document.createElement('img');
                img.src = logo.img;
                img.alt = logo.name;
                img.loading = 'lazy';
                img.onerror = function() { this.style.display = 'none'; };
                gridDiv.appendChild(img);
                
                const nameSpan = document.createElement('span');
                nameSpan.className = 'client-name';
                nameSpan.textContent = logo.name;
                
                wrapper.appendChild(gridDiv);
                wrapper.appendChild(nameSpan);
                clientsGrid.appendChild(wrapper); 
            }); 
        }

