        function setActiveNav() {
            var page = document.body.getAttribute('data-page') || 'home';
            document.querySelectorAll('[data-nav]').forEach(function (a) { a.classList.toggle('active', a.getAttribute('data-nav') === page); });
            document.querySelectorAll('[data-mnav]').forEach(function (a) { a.classList.toggle('active', a.getAttribute('data-mnav') === page); });
        }
        function runPreloader() {
            var pre = document.getElementById('preloader');
            if (!pre) return;
            var bar = document.getElementById('preloader-bar');
            if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) { pre.style.display = 'none'; return; }
            var p = 0, done = false, started = Date.now(), minShown = 1200;
            var timer = setInterval(function () {
                if (done) return;
                p += (90 - p) * 0.12 + 0.6;
                if (p > 90) p = 90;
                if (bar) bar.style.width = p.toFixed(1) + '%';
            }, 60);
            function finish() {
                if (pre.classList.contains('done')) return;
                pre.classList.add('done'); clearInterval(timer);
                setTimeout(function () { if (pre.parentNode) pre.parentNode.removeChild(pre); }, 600);
            }
            function complete() {
                done = true;
                if (bar) bar.style.width = '100%';
                var elapsed = Date.now() - started;
                setTimeout(finish, Math.max(0, minShown - elapsed));
            }
            window.addEventListener('load', complete);
            setTimeout(complete, 6000);
        }
